      "new_content": "As of 2026-01-12, the billing API is owned by the Ember team, which the Atlas team owned until then.",
      "entities": [
        "billing API",
        "Ember team",
        "Atlas team"
      ],
      "kind": "decision",
      "confidence": 1,
      "evidence": "billing-api belongs to the Ember team starting today. Thanks to the Atlas team for running it until now."
    }
  ],
  "add_relations": [
    {
      "src": "Ember team",
      "dst": "billing API",
      "rel_kind": "owns",
      "evidence": "billing-api belongs to the Ember team starting today"
    }
  ],
  "remove_relations": [
    {
      "src": "Atlas team",
      "dst": "billing API",
      "rel_kind": "owns",
      "evidence": "Thanks to the Atlas team for running it until now."
    }
  ],
  "entity_aliases": [
    {
      "name": "billing-api",
      "canonical": "billing API",
      "evidence": "billing-api belongs to the Ember team starting today"
    }
  ]
}

